 public partial class Controller {
  List<Song> BatchSelection(){var songs=SelectedSongs();return songs.Count>0?songs:AllSongs.ToList();}
  readonly AudioInputSelection gainInputs=new AudioInputSelection(true),conversionInputs=new AudioInputSelection();
  void OpenAudioTools(){var panel=ModulePage("MP3Gain","Verlustfreie Lautstärkeanpassung der zentral ausgewählten Original-MP3-Dateien.");var buttons=ModuleButtons(panel);var target=new StudioNumericUpDown{Minimum=75,Maximum=105,Value=89,Width=75};buttons.Controls.Add(new Label{Text="Zielpegel (dB)",AutoSize=true});buttons.Controls.Add(target);var log=ModuleLog(panel);var progress=new StudioProgressBar{Dock=DockStyle.Bottom,Height=18,Maximum=100};panel.Controls.Add(progress);
   Action<string> perform=async mode=>{var songs=SelectedSongs();if(songs.Count==0){AppMessage.Show(v,"Bitte MP3-Titel in der zentralen Liste auswählen.");return;}double db=(double)target.Value;await RunStudioBatch("MP3Gain · "+mode,token=>BatchGain.ApplyOriginals(songs,p.GainExecutable,mode,db,()=>token.ThrowIfCancellationRequested(),text=>UI(()=>{if(!log.IsDisposed){log.Text=text;var m=System.Text.RegularExpressions.Regex.Matches(text,@"(\d+) / (\d+) Dateien");if(m.Count>0){var last=m[m.Count-1];int n=Int32.Parse(last.Groups[1].Value),total=Int32.Parse(last.Groups[2].Value);progress.Value=Math.Min(100,n*100/Math.Max(1,total));}}})),text=>{if(!log.IsDisposed)log.AppendText("\r\n"+text);});};
   foreach(var pair in new[]{Tuple.Create("Titelanalyse","Analyse"),Tuple.Create("Albumanalyse","Albumanalyse"),Tuple.Create("Track-Gain anwenden","Track"),Tuple.Create("Album-Gain anwenden","Album"),Tuple.Create("Gain zurücknehmen","Undo")}){var action=pair;buttons.Controls.Add(MainView.StudioButton(action.Item1,()=>perform(action.Item2)));}buttons.Controls.Add(MainView.StudioButton("Abbrechen",()=>{if(cancel!=null)cancel.Cancel();}));v.ShowModule(panel,SelectWorkingPaths);
  }
  void OpenConversion(){OpenAudioEngine(false);return;}
  void OpenLegacyConversion(){var panel=ModulePage("Audio-Konvertierung","Audiodateien hierher ziehen oder die Bibliotheksauswahl konvertieren. Ausgabe erfolgt in einem neuen Ordner; Originale bleiben erhalten.");var buttons=ModuleButtons(panel);var format=new StudioComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=110};format.Items.AddRange(new object[]{"MP3","FLAC","WAV","OGG","M4A","OPUS"});format.SelectedIndex=0;var bitrate=new StudioComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=130};bitrate.Items.AddRange(new object[]{128,160,192,224,256,320});bitrate.SelectedItem=192;var variable=new CheckBox{Text="MP3 VBR (V2)",AutoSize=true};var log=ModuleLog(panel);log.Name="Konvertierungs-Dateien";
   Action showInputs=()=>{log.Text=conversionInputs.Songs.Count==0?"Audiodateien oder Ordner hierher ziehen. Alternativ werden markierte oder geladene Titel aus der Bibliothek verwendet.":conversionInputs.Songs.Count+" Audiodateien für die Konvertierung bereit.\r\n\r\n"+String.Join("\r\n",conversionInputs.Songs.Select(x=>x.Artist+" – "+x.Title+"\r\n"+x.Source));};showInputs();var menu=new ContextMenuStrip();menu.Items.Add("Dateiauswahl leeren",null,(s,e)=>{if(!busy){conversionInputs.Clear();showInputs();}});log.ContextMenuStrip=menu;
   buttons.Controls.Add(format);buttons.Controls.Add(bitrate);buttons.Controls.Add(variable);buttons.Controls.Add(MainView.StudioButton("Konvertieren …",async()=>{var songs=conversionInputs.Songs.Count>0?conversionInputs.Songs:BatchSelection();if(songs.Count==0){AppMessage.Show(v,"Bitte zuerst Audiodateien ablegen oder Musik importieren.");return;}string parent;using(var d=new AppFolderDialog{Description="Ziel für konvertierte Dateikopien"}){if(d.ShowDialog(v)!=DialogResult.OK)return;parent=d.SelectedPath;}string type=(string)format.SelectedItem;int rate=(int)bitrate.SelectedItem;bool vbr=variable.Checked;await RunStudioBatch("Konvertierung",token=>AudioConversion.Convert(songs,parent,type,rate,vbr,p.FfmpegExecutable,()=>token.ThrowIfCancellationRequested()));},true));buttons.Controls.Add(MainView.StudioButton("Audio-Einstellungen",()=>Run(GainSettings)));v.ShowModule(panel,paths=>LoadToolInputs(conversionInputs,paths,log,showInputs));}
  async void LoadToolInputs(AudioInputSelection inputs,string[] paths,TextBox log,Action showInputs){
   if(busy)return;cancel=new CancellationTokenSource();var token=cancel.Token;SetBusy(true);log.Text="Audiodateien werden eingelesen …";
   try{await Task.Run(()=>inputs.Add(paths,()=>token.ThrowIfCancellationRequested()));if(!log.IsDisposed)showInputs();}
   catch(OperationCanceledException){if(!log.IsDisposed){showInputs();log.AppendText("\r\n\r\nEinlesen abgebrochen.");}}
   catch(Exception ex){if(!log.IsDisposed){showInputs();log.AppendText("\r\n\r\n"+ex.Message);}}
   finally{cancel.Dispose();cancel=null;SetBusy(false);}
  }
  void OpenStatistics(){var panel=ModulePage("Statistiken","Übersicht der aktuell geladenen Musikbibliothek.");var grid=new StudioSongGrid{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};grid.Columns.Add("Bereich","Bereich");grid.Columns.Add("Wert","Wert");var songs=AllSongs.ToList();grid.Rows.Add("Titel",songs.Count);grid.Rows.Add("Ordner",p.Folders.Count);grid.Rows.Add("Alben",songs.Select(s=>s.Album).Distinct(StringComparer.OrdinalIgnoreCase).Count());grid.Rows.Add("Interpreten",songs.Select(s=>s.Artist).Distinct(StringComparer.OrdinalIgnoreCase).Count());grid.Rows.Add("Gesamtdauer",TimeSpan.FromSeconds(songs.Sum(s=>s.Duration)).ToString(@"d\ \T\a\g\e\ hh\:mm\:ss"));grid.Rows.Add("Fehlende Quelldateien",songs.Count(s=>!File.Exists(s.Source)));grid.Rows.Add("Mögliche Dubletten",songs.GroupBy(s=>LibrarySearch.Compact(s.Artist)+"|"+LibrarySearch.Compact(s.Title)).Where(g=>g.Count()>1).Sum(g=>g.Count()-1));foreach(var g in songs.GroupBy(s=>Path.GetExtension(s.Source).ToUpperInvariant()).OrderBy(g=>g.Key))grid.Rows.Add("Format "+g.Key,g.Count());panel.Controls.Add(grid);StudioScrollbars.Surface(grid).BringToFront();v.ShowModule(panel);}
  void OpenPlaylists(){if(playlistOrder==null)playlistOrder=new List<Song>();var panel=ModulePage("Wiedergabelisten","M3U8-Listen laden, speichern, ordnen und abspielen. Die Reihenfolge gilt beim Weiter-/Zurückspringen im Player.");var buttons=ModuleButtons(panel);var list=new StudioListBox{Dock=DockStyle.Fill,SelectionMode=SelectionMode.MultiExtended};Action refreshList=()=>{list.Items.Clear();foreach(var s in playlistOrder)list.Items.Add((s.Artist??"")+" – "+s.Title);};refreshList();panel.Controls.Add(list);StudioScrollbars.Surface(list).BringToFront();Action add=()=>{foreach(var s in BatchSelection())if(!playlistOrder.Any(x=>String.Equals(x.Source,s.Source,StringComparison.OrdinalIgnoreCase)))playlistOrder.Add(s);refreshList();};buttons.Controls.Add(MainView.StudioButton("Auswahl hinzufügen",add,true));buttons.Controls.Add(MainView.StudioButton("Entfernen",()=>{foreach(int i in list.SelectedIndices.Cast<int>().OrderByDescending(x=>x).ToArray())playlistOrder.RemoveAt(i);refreshList();}));Action<int> move=delta=>{int i=list.SelectedIndex,j=i+delta;if(i<0||j<0||j>=playlistOrder.Count)return;var song=playlistOrder[i];playlistOrder.RemoveAt(i);playlistOrder.Insert(j,song);refreshList();list.SelectedIndex=j;};buttons.Controls.Add(MainView.StudioButton("↑",()=>move(-1)));buttons.Controls.Add(MainView.StudioButton("↓",()=>move(1)));buttons.Controls.Add(MainView.StudioButton("Abspielen",()=>{if(list.SelectedIndex<0&&playlistOrder.Count>0)list.SelectedIndex=0;if(list.SelectedIndex>=0)RunPlayback(()=>{LoadPlayer(playlistOrder[list.SelectedIndex]);StartPlayer();});}));buttons.Controls.Add(MainView.StudioButton("Laden …",()=>{using(var d=new AppOpenFileDialog{Filter="Wiedergabeliste|*.m3u;*.m3u8"})if(d.ShowDialog(v)==DialogResult.OK){try{var loaded=PlaylistFiles.Load(d.FileName,AllSongs);playlistOrder=loaded;refreshList();}catch(Exception ex){AppMessage.Show(v,ex.Message,"Wiedergabeliste");}}}));buttons.Controls.Add(MainView.StudioButton("Speichern …",()=>{using(var d=new AppSaveFileDialog{Filter="UTF-8-Wiedergabeliste|*.m3u8",FileName="Musikbox-Wiedergabeliste.m3u8"})if(d.ShowDialog(v)==DialogResult.OK)PlaylistFiles.Save(d.FileName,playlistOrder);}));buttons.Controls.Add(MainView.StudioButton("Bibliotheksreihenfolge",()=>{playlistOrder.Clear();refreshList();}));list.DoubleClick+=(s,e)=>{if(list.SelectedIndex>=0)RunPlayback(()=>{LoadPlayer(playlistOrder[list.SelectedIndex]);StartPlayer();});};v.ShowModule(panel);}
 }
 public static class AudioConversion {
  public static string Convert(IList<Song> songs,string parent,string format,int bitrate,bool vbr,string ffmpeg,Action check){if(!File.Exists(ffmpeg))throw new FileNotFoundException("ffmpeg.exe fehlt.",ffmpeg);var codecs=new Dictionary<string,string>{{"MP3","libmp3lame"},{"FLAC","flac"},{"WAV","pcm_s16le"},{"OGG","libvorbis"},{"M4A","aac"},{"OPUS","libopus"}};if(!codecs.ContainsKey(format))throw new ArgumentException("Unbekanntes Zielformat.");string stage=BatchFiles.Stage(parent);try{for(int i=0;i<songs.Count;i++){check();var s=songs[i];string path=Path.Combine(stage,(i+1).ToString("D4")+" - "+Rules.SafeName(s.Artist+" - "+s.Title)+"."+format.ToLowerInvariant());string rate=format=="MP3"?(vbr?"-q:a 2":"-b:a "+bitrate+"k"):format=="OGG"?"-q:a 6":format=="OPUS"?"-b:a 160k":format=="M4A"?"-b:a "+bitrate+"k":"";string err;Ffmpeg.Run(ffmpeg,"-hide_banner -nostdin -v error -n -i "+Ffmpeg.Quote(s.Source)+" -map 0:a:0 -vn -c:a "+codecs[format]+" "+rate+" "+Ffmpeg.Quote(path),check,out err);MediaMetadata.Write(path,s,s.Album??"");MediaMetadata.PreserveArtwork(s.Source,path,s);if(new FileInfo(path).Length==0)throw new Exception("Leere Ausgabedatei.");}check();return BatchFiles.Commit(stage,"Konvertierung");}catch{BatchFiles.Cleanup(stage);throw;}}
 }
 public static class PlaylistFiles {
  public static List<Song> Load(string path,IEnumerable<Song> library){if(new FileInfo(path).Length>10*1024*1024)throw new Exception("Wiedergabeliste zu groß.");var known=library.ToList();var result=new List<Song>();foreach(string line in File.ReadAllLines(path,Encoding.UTF8)){string entry=line.Trim();if(entry.Length==0||entry.StartsWith("#"))continue;if(entry.IndexOf("://",StringComparison.Ordinal)>=0)throw new Exception("Nur lokale Musikdateien werden unterstützt.");string full=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(path),entry));if(!File.Exists(full))throw new FileNotFoundException("Titel aus der Wiedergabeliste fehlt.",full);if(!Ffmpeg.Extensions.Contains(Path.GetExtension(full).ToLowerInvariant()))throw new Exception("Keine unterstützte Audiodatei: "+full);result.Add(known.FirstOrDefault(s=>String.Equals(Path.GetFullPath(s.Source),full,StringComparison.OrdinalIgnoreCase))??MediaMetadata.Read(full));}return result;}
  public static void Save(string path,IEnumerable<Song> songs){var lines=new List<string>{"#EXTM3U"};foreach(var song in songs){lines.Add("#EXTINF:"+(int)song.Duration+","+(song.Artist+" - "+song.Title).Replace("\r"," ").Replace("\n"," "));lines.Add(Path.GetFullPath(song.Source));}File.WriteAllLines(path,lines,new UTF8Encoding(true));}
 }
 public static class BatchGain {
  static string Run(string exe,string directory,string args,Action check){if(!File.Exists(exe))throw new FileNotFoundException("Das mitgelieferte mp3gain.exe fehlt.",exe);check();var start=new System.Diagnostics.ProcessStartInfo{FileName=Path.GetFullPath(exe),Arguments=args,WorkingDirectory=directory,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=System.Diagnostics.Process.Start(start)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();var watch=System.Diagnostics.Stopwatch.StartNew();try{while(!process.WaitForExit(100)){check();if(watch.Elapsed.TotalMinutes>60)throw new Exception("MP3Gain-Zeitlimit überschritten.");}check();}catch{try{process.Kill();}catch{}throw;}Task.WaitAll(output,error);string text=output.Result+"\r\n"+error.Result;if(process.ExitCode<0||process.ExitCode>1||System.Text.RegularExpressions.Regex.IsMatch(text,@"\b(error|can't|cannot|could not|failed|not enough samples)\b",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new Exception("MP3Gain-Verarbeitung fehlgeschlagen:\r\n"+text);return text;}}
  public static string Analyze(IList<Song> songs,string exe,Action check,Action<string> progress=null){return Direct(songs,exe,"Analyse",89,check,progress);}
  public static string AnalyzeAlbums(IList<Song> songs,string exe,Action check,Action<string> progress=null){return Direct(songs,exe,"Albumanalyse",89,check,progress);}
  public static string ApplyOriginals(IList<Song> songs,string exe,string mode,double db,Action check,Action<string> progress=null){return Direct(songs,exe,mode,db,check,progress);}
  static string Direct(IList<Song> songs,string exe,string mode,double db,Action check,Action<string> progress){if(!new[]{"Analyse","Albumanalyse","Track","Album","Undo"}.Contains(mode))throw new ArgumentException("Unbekannte MP3Gain-Aktion.");if(Double.IsNaN(db)||Double.IsInfinity(db)||db<75||db>105)throw new ArgumentException("Ungültiger Zielpegel.");var unique=songs.GroupBy(s=>Path.GetFullPath(s.Source),StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToArray();if(unique.Length==0)throw new ArgumentException("Bitte MP3-Titel in der zentralen Liste auswählen.");foreach(var song in unique){check();if(!Ffmpeg.IsMp3(song.Source)||!File.Exists(song.Source))throw new IOException("Keine erreichbare MP3-Datei: "+song.Source);if(mode!="Analyse"&&mode!="Albumanalyse")using(var stream=new FileStream(song.Source,FileMode.Open,FileAccess.ReadWrite,FileShare.Read)){} }
   var groups=mode=="Album"||mode=="Albumanalyse"?unique.GroupBy(s=>(s.Album??"")+"\n"+Path.GetDirectoryName(Path.GetFullPath(s.Source)),StringComparer.OrdinalIgnoreCase).Select(g=>g.ToList()).ToList():unique.Select((song,index)=>new{Song=song,Group=index/32}).GroupBy(x=>x.Group).Select(g=>g.Select(x=>x.Song).ToList()).ToList();var result=new StringBuilder();int done=0;
   foreach(var group in groups){check();string operation=mode=="Undo"?"-u":mode=="Analyse"||mode=="Albumanalyse"?"-s s":(mode=="Album"?"-a":"-r")+" -k -s r -d "+(db-89).ToString("0.0",CultureInfo.InvariantCulture);string args=operation+" -o "+String.Join(" ",group.Select(s=>Ffmpeg.Quote(Path.GetFullPath(s.Source))));if(args.Length>28000)throw new IOException("Albumauswahl überschreitet die Befehlszeilenlänge.");if(progress!=null)progress(result+done.ToString()+" / "+unique.Length+" Dateien · "+mode);if(mode!="Analyse"&&mode!="Albumanalyse")foreach(var song in group)song.PreparedSource=song.PreparedProfile=null;result.AppendLine(Run(exe,Path.GetDirectoryName(Path.GetFullPath(group[0].Source)),args,check));done+=group.Count;result.AppendLine(done+" / "+unique.Length+" Dateien abgeschlossen");if(progress!=null)progress(result.ToString());}return result.ToString();}
  public static string WriteCopies(IList<Song> songs,string exe,string parent,string mode,double db,Action check){string stage=BatchFiles.Stage(parent);try{var groups=mode=="Album"?songs.GroupBy(s=>(s.Album??"")+"\n"+Path.GetDirectoryName(s.Source)).Select(g=>g.ToList()).ToList():songs.Select((song,index)=>new{Song=song,Group=index/128}).GroupBy(x=>x.Group).Select(g=>g.Select(x=>x.Song).ToList()).ToList();var log=new StringBuilder();int count=0;foreach(var group in groups){string work=Path.Combine(stage,"work");Directory.CreateDirectory(work);var paths=new List<string>();for(int i=0;i<group.Count;i++){string name=i.ToString("D5")+".mp3";File.Copy(group[i].Source,Path.Combine(work,name));paths.Add(name);}string args=mode=="Undo"?"-u":(mode=="Album"?"-a":"-r")+" -k -s r -d "+(db-89).ToString("0.0",CultureInfo.InvariantCulture);log.AppendLine(Run(exe,work,args+" -o "+String.Join(" ",paths),check));for(int i=0;i<group.Count;i++){check();var song=group[i];var verify=MediaMetadata.Read(Path.Combine(work,paths[i]));if(verify.Duration<=0)throw new Exception("MP3Gain-Ausgabe enthält keine lesbare Audiospur.");MediaMetadata.Write(Path.Combine(work,paths[i]),song,song.Album??"");File.Move(Path.Combine(work,paths[i]),Path.Combine(stage,(++count).ToString("D4")+" - "+Rules.SafeName(song.Artist+" - "+song.Title)+".mp3"));}Directory.Delete(work);}File.WriteAllText(Path.Combine(stage,"MP3Gain-Protokoll.txt"),log.ToString(),Encoding.UTF8);check();return BatchFiles.Commit(stage,"MP3Gain-"+mode);}catch{BatchFiles.Cleanup(stage);throw;}}
 }
